insert into public.exercises (name, muscle_group, description, category, movement_pattern, image_url) values
('Überzüge mit Kurzhantel', 'Latissimus, Brust, Trizeps', 'Ausführung: Quer auf einer Bank liegend (nur Schultern aufliegend) eine Kurzhantel mit beiden Händen über der Brust halten und mit leicht gebeugten Armen hinter den Kopf absenken, bis eine Dehnung im Latissimus spürbar ist, dann zurückführen. Ausrüstung: Kurzhantel, Bank. Worauf achten: Hüfte tief halten, Rippenbogen nicht überstrecken, Ellbogenwinkel während der gesamten Bewegung beibehalten.', 'Kraft', 'pull_oberkoerper', null),
('Überzüge am Kabelzug', 'Latissimus, Brust', 'Ausführung: Am hohen Kabelzug mit gestreckten Armen die Stange oder das Seil in einer Bogenbewegung von oben bis vor die Oberschenkel ziehen, kontrolliert zurückführen. Ausrüstung: Kabelzug mit Stangen- oder Seilgriff. Worauf achten: Arme bleiben nahezu gestreckt, Bewegung kommt aus dem Latissimus, Oberkörper leicht vorgebeugt und stabil.', 'Kraft', 'pull_oberkoerper', null),
('V-Lift mit Band', 'Schulter, Trapez', 'Ausführung: Im Stand oder in Bauchlage das Band mit beiden Händen in V-Form diagonal über Kopf nach oben-außen ziehen, Schulterblätter dabei zusammenziehen, kontrolliert zurückführen. Ausrüstung: Widerstandsband. Worauf achten: Bewegung kommt aus dem oberen Rücken, kein Hohlkreuz, Ellbogen bleiben lang.', 'Kraft', 'pull_oberkoerper', null),
('V-Lift mit Kurzhantel', 'Schulter, Trapez', 'Ausführung: In Bauchlage auf einer Schrägbank die Arme mit leichten Kurzhanteln diagonal nach vorn-oben in Y-Form anheben, Schulterblätter zusammenziehen, kontrolliert absenken. Ausrüstung: leichte Kurzhanteln, Schrägbank. Worauf achten: Sehr geringes Gewicht wählen, Bewegung langsam und kontrolliert, kein Schwung.', 'Kraft', 'pull_oberkoerper', null),
('Außenrotationen für die Schulter', 'Schulter', 'Ausführung: Ellbogen im 90°-Winkel am Körper fixiert (Handtuch/Kissen unter der Achsel), den Unterarm mit leichter Kurzhantel oder Band nach außen rotieren, kontrolliert zurückführen. Ausrüstung: leichte Kurzhantel oder Widerstandsband. Worauf achten: Ellbogen bleibt während der gesamten Bewegung am Körper fixiert, sehr geringes Gewicht, Fokus auf die Rotatorenmanschette.', 'Kraft', 'pull_oberkoerper', null),
('Innenrotationen für die Schulter', 'Schulter', 'Ausführung: Ellbogen im 90°-Winkel am Körper fixiert, den Unterarm mit leichter Kurzhantel oder Band vor dem Bauch nach innen rotieren, kontrolliert zurückführen. Ausrüstung: leichte Kurzhantel oder Widerstandsband. Worauf achten: Ellbogen bleibt fixiert, kontrolliertes Tempo, kein Schwung aus der Schulter.', 'Kraft', 'push_oberkoerper', null),
('Negativ-Bankdrücken (Langhantel)', 'Brust, Trizeps', 'Ausführung: Auf der Negativbank (Kopf tiefer als Becken) liegend die Langhantel von der Brust nach oben drücken, kontrolliert absenken. Ausrüstung: Langhantel, Negativbank. Worauf achten: Sicherung/Spotter verwenden, Schulterblätter fixiert, Stange kontrolliert im unteren Brustbereich aufsetzen.', 'Kraft', 'push_oberkoerper', null),
('Kurzhantel-Schulterdrücken (sitzend)', 'Schulter, Trizeps', 'Ausführung: Sitzend mit Rückenlehne die Kurzhanteln von Schulterhöhe nach oben drücken, bis die Arme fast gestreckt sind, kontrolliert absenken. Ausrüstung: Kurzhanteln, Bank mit Rückenlehne. Worauf achten: Rücken an der Lehne, kein Hohlkreuz, Handgelenke gerade über den Ellbogen.', 'Kraft', 'push_oberkoerper', null),
('Langhantelrudern im Untergriff', 'Latissimus, Bizeps, Trapez', 'Ausführung: Vorgebeugt mit Untergriff (Handflächen nach oben) die Langhantel zum Bauch heranziehen, Ellbogen eng am Körper, kontrolliert absenken. Ausrüstung: Langhantel. Worauf achten: Rücken gerade und Oberkörperwinkel stabil halten, kein Schwung aus dem unteren Rücken.', 'Kraft', 'pull_oberkoerper', null),
('T-Bar-Rudern', 'Latissimus, Trapez, Bizeps', 'Ausführung: Über der T-Bar-Stange stehend, Oberkörper vorgebeugt, den Griff zum Bauch heranziehen, Schulterblätter zusammenziehen, kontrolliert absenken. Ausrüstung: T-Bar-Rudergerät oder Langhantel in der Ecke mit V-Griff. Worauf achten: Rücken gerade, Knie leicht gebeugt, Zug aus dem Rücken statt aus den Armen.', 'Kraft', 'pull_oberkoerper', null),
('Rumänisches Kreuzheben (Langhantel)', 'Oberschenkel, Gesäß, Rückenstrecker', 'Ausführung: Mit fast gestreckten Beinen die Langhantel eng am Körper entlang absenken, bis eine Dehnung in der Oberschenkelrückseite spürbar ist, dann über die Hüfte wieder aufrichten. Ausrüstung: Langhantel. Worauf achten: Rücken gerade, Bewegung aus der Hüfte, Stange bleibt körpernah.', 'Kraft', 'hintere_beinkette', null),
('Frontkniebeuge (Langhantel)', 'Oberschenkel, Gesäß', 'Ausführung: Die Langhantel vorn auf den Schultern ablegen (Clean-Griff oder verschränkte Arme), in die Kniebeuge absenken und wieder aufstehen. Ausrüstung: Langhantel, ggf. Squat-Rack. Worauf achten: Oberkörper aufrecht halten, Ellbogen hoch, Knie in Fußrichtung.', 'Kraft', 'vordere_beinkette', null),
('Hackenschmidt-Maschine (Hack Squat)', 'Oberschenkel, Gesäß', 'Ausführung: Mit dem Rücken an der geneigten Rückenplatte der Maschine in die Kniebeuge absenken, dann durch Strecken der Beine wieder aufstehen. Ausrüstung: Hackenschmidt-Maschine. Worauf achten: Rücken bleibt an der Platte, Knie in Fußrichtung, kontrolliertes Tempo ohne Durchstoßen der Knie.', 'Kraft', 'vordere_beinkette', null),
('Rückwärtiger Ausfallschritt mit der Langhantel', 'Oberschenkel, Gesäß', 'Ausführung: Mit der Langhantel im Nacken einen großen Schritt rückwärts setzen, das hintere Knie Richtung Boden absenken, dann zurück in den Stand drücken. Ausrüstung: Langhantel. Worauf achten: Oberkörper aufrecht, vorderes Knie bleibt über dem Fuß, kontrolliertes Tempo.', 'Kraft', 'vordere_beinkette', null),
('Konzentrationscurls mit Kurzhantel', 'Bizeps', 'Ausführung: Sitzend den Ellbogen an der Innenseite des Oberschenkels abstützen und die Kurzhantel durch Beugen des Arms nach oben führen, kontrolliert absenken. Ausrüstung: Kurzhantel, Bank. Worauf achten: Oberarm bleibt fixiert, Bewegung isoliert im Ellbogengelenk, kein Schwung.', 'Kraft', 'pull_oberkoerper', null),
('Enges Bankdrücken (Close-Grip)', 'Trizeps, Brust', 'Ausführung: Auf der Flachbank liegend die Langhantel mit schulterbreitem oder engerem Griff von der Brust nach oben drücken, Ellbogen eng am Körper führen, kontrolliert absenken. Ausrüstung: Langhantel, Bank. Worauf achten: Ellbogen zeigen nach hinten statt nach außen, Handgelenke gerade, Sicherung/Spotter bei hohem Gewicht.', 'Kraft', 'push_oberkoerper', null),
('Dips an der Assistenzmaschine', 'Brust, Trizeps', 'Ausführung: Auf der Kniestütze der Assistenzmaschine den Oberkörper zwischen den Griffen absenken, bis die Ellbogen etwa 90° gebeugt sind, dann wieder nach oben drücken. Ausrüstung: Dip-/Klimmzug-Assistenzmaschine. Worauf achten: Gewichtsunterstützung so wählen, dass die Bewegung sauber gelingt, leichte Vorlage für mehr Brust- oder aufrechte Haltung für mehr Trizepsbeteiligung.', 'Kraft', 'push_oberkoerper', null),
('Shrugs mit der Langhantel', 'Trapez', 'Ausführung: Im Stand die Langhantel vor dem Körper halten und die Schultern gerade nach oben Richtung Ohren ziehen, kurz halten, kontrolliert absenken. Ausrüstung: Langhantel. Worauf achten: Keine Rollbewegung in den Schultern, Bewegung rein vertikal, Nacken entspannt.', 'Kraft', 'pull_oberkoerper', null),
('Shrugs mit Kurzhanteln', 'Trapez', 'Ausführung: Im Stand mit einer Kurzhantel in jeder Hand die Schultern gerade nach oben ziehen, kurz halten, kontrolliert absenken. Ausrüstung: Kurzhanteln. Worauf achten: Keine Rollbewegung, Bewegung rein vertikal, aufrechter Stand.', 'Kraft', 'pull_oberkoerper', null),
('Beinadduktion am Kabelzug', 'Oberschenkel', 'Ausführung: Seitlich zum unteren Kabelzug stehend mit Fußmanschette das äußere Bein vor dem Standbein nach innen führen, kontrolliert zurückführen. Ausrüstung: Kabelzug mit Fußmanschette. Worauf achten: Oberkörper stabil, Bewegung kontrolliert ohne Schwung, Halt am Gerät zur Balance.', 'Kraft', 'sonstige', null),
('Beinabduktion am Kabelzug', 'Gesäß', 'Ausführung: Seitlich zum unteren Kabelzug stehend mit Fußmanschette das innere Bein seitlich vom Körper wegführen, kontrolliert zurückführen. Ausrüstung: Kabelzug mit Fußmanschette. Worauf achten: Oberkörper aufrecht, Bewegung aus der Hüfte, kein Ausweichen ins Hohlkreuz.', 'Kraft', 'sonstige', null),
('Scott-Curls (SZ-Stange)', 'Bizeps', 'Ausführung: Die Oberarme auf der Schrägpolsterung des Scott-Pults ablegen und die SZ-Stange durch Beugen der Ellbogen nach oben führen, kontrolliert absenken. Ausrüstung: SZ-Stange, Scott-Pult (Preacher-Bank). Worauf achten: Oberarme bleiben auf dem Polster, Bewegung nicht bis zur vollen Streckung mit Schwung beenden.', 'Kraft', 'pull_oberkoerper', null),
('Trizeps-Kickback mit Kurzhantel', 'Trizeps', 'Ausführung: Vorgebeugt mit einer Hand und einem Knie auf der Bank abgestützt, den Oberarm parallel zum Rücken halten und den Unterarm mit der Kurzhantel nach hinten strecken, kontrolliert zurückführen. Ausrüstung: Kurzhantel, Bank. Worauf achten: Oberarm bleibt während der gesamten Bewegung ruhig, Bewegung ausschließlich im Ellbogengelenk.', 'Kraft', 'push_oberkoerper', null),
('Kabelzug-Frontheben', 'Schulter', 'Ausführung: Am unteren Kabelzug stehend mit einer Hand den Griff vor dem Körper bis auf Schulterhöhe anheben, kontrolliert absenken. Ausrüstung: Kabelzug mit Einzelgriff. Worauf achten: Leichte Beugung im Ellbogen beibehalten, kein Schwung aus dem Rumpf, konstante Spannung im Kabel.', 'Kraft', 'push_oberkoerper', null),
('Kabelzug-Seitheben', 'Schulter', 'Ausführung: Seitlich zum unteren Kabelzug stehend mit der außenliegenden Hand den Griff seitlich bis auf Schulterhöhe anheben, kontrolliert absenken. Ausrüstung: Kabelzug mit Einzelgriff. Worauf achten: Oberkörper stabil, kein Schwung aus der Hüfte, konstante Spannung im Kabel während der gesamten Bewegung.', 'Kraft', 'push_oberkoerper', null),
('Gesäßmaschine (Hüftstrecker-Maschine)', 'Gesäß', 'Ausführung: An der Maschine mit angewinkeltem Bein das Polster durch Strecken der Hüfte nach hinten drücken, kontrolliert zurückführen. Ausrüstung: Hüftstrecker-/Gesäßmaschine. Worauf achten: Oberkörper stabil an der Auflage, Bewegung aus der Hüfte, Gesäß am Endpunkt aktiv anspannen.', 'Kraft', 'hintere_beinkette', null),
('Beinpresse einbeinig', 'Oberschenkel, Gesäß', 'Ausführung: An der Beinpresse mit nur einem Bein die Plattform nach oben drücken, kontrolliert bis zum rechten Winkel im Knie absenken, Seite wechseln. Ausrüstung: Beinpresse. Worauf achten: Knie in Fußrichtung, unterer Rücken bleibt an der Lehne, geringeres Gewicht als beidbeinig wählen.', 'Kraft', 'vordere_beinkette', null),
('Wadenheben an der Beinpresse', 'Waden', 'Ausführung: An der Beinpresse mit gestreckten Beinen nur über die Fußballen auf die Plattform drücken, Fersen maximal anheben, kontrolliert bis zur Dehnung absenken. Ausrüstung: Beinpresse. Worauf achten: Beine bleiben nahezu gestreckt, volle Bewegungsamplitude, kein Wippen.', 'Kraft', 'hintere_beinkette', null),
('Good Mornings (Langhantel)', 'Oberschenkel, Rückenstrecker, Gesäß', 'Ausführung: Mit der Langhantel im Nacken den Oberkörper aus der Hüfte nach vorn beugen, bis eine Dehnung in der Oberschenkelrückseite spürbar ist, dann über die Hüfte wieder aufrichten. Ausrüstung: Langhantel. Worauf achten: Rücken während der gesamten Bewegung gerade, Knie nur leicht gebeugt, geringes Gewicht wählen.', 'Kraft', 'hintere_beinkette', null),
('Diagonale Crunches', 'Bauchmuskeln', 'Ausführung: In Rückenlage mit angewinkelten Beinen abwechselnd den Ellbogen zum gegenüberliegenden Knie führen, während das andere Bein gestreckt bleibt. Ausrüstung: Matte. Worauf achten: Bewegung aus der Bauchmuskulatur, unteren Rücken am Boden lassen, kontrolliertes Tempo ohne Zug am Nacken.', 'Bodyweight', 'rumpf_vorne', null),
('Diamant-Liegestütz', 'Brust, Trizeps', 'Ausführung: Liegestütz mit Händen dicht zusammen unter der Brust (Daumen und Zeigefinger bilden eine Raute), Körper absenken und wieder nach oben drücken. Ausrüstung: Matte. Worauf achten: Rumpf und Gesäß angespannt, Ellbogen nah am Körper, bei Bedarf auf den Knien ausführen.', 'Bodyweight', 'push_oberkoerper', null),
('Archer-Liegestütz', 'Brust, Trizeps, Schulter', 'Ausführung: Aus breiter Liegestützposition den Körper zu einer Seite absenken, während der andere Arm gestreckt zur Seite ausgestreckt bleibt, dann zurück in die Mitte drücken und Seite wechseln. Ausrüstung: Matte. Worauf achten: Rumpf stabil, kontrolliertes Tempo, bei Bedarf mit den Knien am Boden ausführen.', 'Bodyweight', 'push_oberkoerper', null),
('Klappmesser (V-Ups)', 'Bauchmuskeln', 'Ausführung: In Rückenlage mit gestreckten Armen und Beinen gleichzeitig Oberkörper und Beine anheben, Hände Richtung Füße führen, kontrolliert zurück in die Ausgangsposition. Ausrüstung: Matte. Worauf achten: Bewegung aus der Bauchmuskulatur, unteren Rücken nicht überlasten, bei Bedarf Beine angewinkelt ausführen.', 'Bodyweight', 'rumpf_vorne', null),
('Russian Twists (ohne Gewicht)', 'Bauchmuskeln', 'Ausführung: Im Sitzen mit leicht angehobenen, angewinkelten Beinen den Oberkörper zurücklehnen und abwechselnd mit den Händen den Boden neben der Hüfte berühren. Ausrüstung: Matte. Worauf achten: Rücken gerade halten, Bewegung aus der Rumpfrotation, kontrolliertes Tempo.', 'Bodyweight', 'rumpf_vorne', null),
('Beckenlift einbeinig', 'Gesäß, Oberschenkel', 'Ausführung: In Rückenlage mit einem aufgestellten Bein das andere Bein strecken und die Hüfte anheben, bis Schultern-Hüfte-Knie eine Linie bilden, kontrolliert absenken. Ausrüstung: Matte. Worauf achten: Becken bleibt gerade, kein Ausweichen zur Seite, Gesäß aktiv anspannen.', 'Bodyweight', 'hintere_beinkette', null),
('Wandsitz (Wall Sit)', 'Oberschenkel', 'Ausführung: Mit dem Rücken an der Wand in die Kniebeuge-Position gehen, bis die Oberschenkel etwa parallel zum Boden sind, Position statisch halten. Ausrüstung: Wand. Worauf achten: Knie über den Fußgelenken, Rücken flächig an der Wand, gleichmäßige Atmung während des Haltens.', 'Bodyweight', 'vordere_beinkette', null),
('Ausfallschritte im Gehen (ohne Gewicht)', 'Oberschenkel, Gesäß', 'Ausführung: Im Gehen abwechselnd große Schritte nach vorn setzen, das hintere Knie Richtung Boden absenken, dann in den nächsten Schritt übergehen. Ausrüstung: keine. Worauf achten: Oberkörper aufrecht, vorderes Knie bleibt über dem Fuß, kontrolliertes Tempo.', 'Bodyweight', 'vordere_beinkette', null),
('Kniebeuge (Bodyweight)', 'Oberschenkel, Gesäß', 'Ausführung: Im hüftbreiten Stand das Gesäß nach hinten-unten absenken, bis die Oberschenkel etwa parallel zum Boden sind, dann wieder aufstehen. Ausrüstung: keine. Worauf achten: Knie in Fußrichtung, Rücken gerade, Gewicht auf der gesamten Fußsohle.', 'Bodyweight', 'vordere_beinkette', null),
('Reverse Plank (Unterarmstütz rückwärts)', 'Bauchmuskeln, Rückenstrecker', 'Ausführung: Im Sitzen mit hinter dem Körper aufgestützten Händen oder Unterarmen die Hüfte anheben, bis der Körper eine gerade Linie bildet, Position halten. Ausrüstung: Matte. Worauf achten: Gesäß aktiv anspannen, Schultern über den Stützpunkten, gleichmäßige Atmung.', 'Bodyweight', 'rumpf_hinten', null),
('Seitstütz mit Hüftheben (Side Plank Hip Dips)', 'Bauchmuskeln', 'Ausführung: Im Unterarm-Seitstütz die Hüfte kontrolliert Richtung Boden absenken und wieder anheben, ohne den Boden zu berühren. Ausrüstung: Matte. Worauf achten: Körper bleibt in einer Linie, Bewegung kommt aus der seitlichen Rumpfmuskulatur, kontrolliertes Tempo.', 'Bodyweight', 'rumpf_vorne', null),
('Beckenlift mit Beinheben (Glute Bridge March)', 'Gesäß, Bauchmuskeln', 'Ausführung: In der Beckenlift-Position die Hüfte oben halten und abwechselnd ein Knie zur Brust heranziehen, ohne die Hüfte absinken zu lassen. Ausrüstung: Matte. Worauf achten: Becken bleibt während des gesamten Übungsablaufs stabil und gerade, Gesäß durchgehend angespannt.', 'Bodyweight', 'hintere_beinkette', null),
('Spiderman-Liegestütz', 'Brust, Trizeps, Bauchmuskeln', 'Ausführung: Während der Abwärtsbewegung eines Liegestützes ein Knie seitlich Richtung Ellbogen ziehen, dann wieder strecken und nach oben drücken, Seite wechseln. Ausrüstung: Matte. Worauf achten: Rumpf stabil, Bewegung kontrolliert, bei Bedarf auf den Knien ausführen.', 'Bodyweight', 'push_oberkoerper', null),
('Pike Push-Up (Schulterliegestütz)', 'Schulter, Trizeps', 'Ausführung: Aus dem umgekehrten V (Hüfte hoch, Hände und Füße am Boden) den Oberkörper absenken, bis der Kopf sich dem Boden nähert, dann wieder nach oben drücken. Ausrüstung: Matte. Worauf achten: Hüfte bleibt hoch, Bewegung wie ein vertikaler Liegestütz, Blick leicht nach hinten zwischen die Hände.', 'Bodyweight', 'push_oberkoerper', null),
('Klimmzug im Untergriff (Chin-Up)', 'Latissimus, Bizeps', 'Ausführung: Mit Untergriff (Handflächen zum Gesicht) an der Stange hängend den Körper nach oben ziehen, bis das Kinn über der Stange ist, kontrolliert absenken. Ausrüstung: Klimmzugstange. Worauf achten: Schultern aktiv nach unten ziehen, kein Schwung, volle Bewegungsamplitude nutzen.', 'Bodyweight', 'pull_oberkoerper', null),
('Australische Klimmzüge (Inverted Row)', 'Latissimus, Bizeps, Trapez', 'Ausführung: Unter einer tief hängenden Stange oder an Ringen mit gestrecktem Körper den Oberkörper zur Stange hochziehen, Schulterblätter zusammenziehen, kontrolliert absenken. Ausrüstung: Klimmzugstange (tief) oder Ringe/Schlaufen. Worauf achten: Körper bleibt in einer geraden Linie, Ferse aufgesetzt, Schwierigkeitsgrad über den Körperwinkel steuern.', 'Bodyweight', 'pull_oberkoerper', null),
('Step-Down (exzentrisches Beintraining)', 'Oberschenkel, Gesäß', 'Ausführung: Auf einer Erhöhung stehend ein Bein langsam kontrolliert nach vorn-unten absenken, bis die Ferse fast den Boden berührt, dann zurück nach oben drücken. Ausrüstung: Stufe oder stabile Erhöhung. Worauf achten: Bewegung sehr langsam und kontrolliert, Knie in Fußrichtung, Standbein trägt die gesamte Kontrolle.', 'Bodyweight', 'vordere_beinkette', null),
('Curtsy Lunge (Reverenz-Ausfallschritt)', 'Oberschenkel, Gesäß', 'Ausführung: Mit einem Bein diagonal hinter das Standbein kreuzen und das hintere Knie Richtung Boden absenken, dann zurück in den Stand drücken. Ausrüstung: keine. Worauf achten: Oberkörper aufrecht, Knie des vorderen Beins bleibt stabil, kontrolliertes Tempo.', 'Bodyweight', 'vordere_beinkette', null),
('Beinheben liegend (Lying Leg Raise)', 'Bauchmuskeln', 'Ausführung: In Rückenlage die gestreckten Beine gemeinsam anheben, bis sie senkrecht stehen, kontrolliert wieder absenken, ohne den unteren Rücken vom Boden abzuheben. Ausrüstung: Matte. Worauf achten: Unterer Rücken bleibt am Boden, Bewegung kontrolliert, bei Bedarf Beine leicht angewinkelt ausführen.', 'Bodyweight', 'rumpf_vorne', null),
('Seitliches Beinheben im Liegen', 'Gesäß, Oberschenkel', 'Ausführung: In Seitlage mit gestrecktem Körper das obere Bein kontrolliert anheben und wieder absenken, ohne dass das Becken nach hinten kippt. Ausrüstung: Matte. Worauf achten: Rumpf stabil, Bewegung isoliert aus der Hüfte, kontrolliertes Tempo ohne Schwung.', 'Bodyweight', 'sonstige', null),
('Unterarmstütz mit Schulterklopfen (Plank Shoulder Taps)', 'Bauchmuskeln, Schulter', 'Ausführung: Im hohen Stütz (Liegestützposition) abwechselnd mit einer Hand die gegenüberliegende Schulter berühren, ohne das Becken zu verdrehen. Ausrüstung: Matte. Worauf achten: Becken bleibt ruhig und gerade, Füße etwas breiter stellen für mehr Stabilität, kontrolliertes Tempo.', 'Bodyweight', 'rumpf_vorne', null),
('Schulterkreisen', 'Schultern', 'Ausführung: Im Stand die Schultern großzügig nach vorn und anschließend nach hinten kreisen lassen. Ausrüstung: keine. Worauf achten: Bewegung groß und langsam ausführen, Arme locker hängen lassen.', 'Mobilisation', 'sonstige', null),
('Nackendehnung im Sitzen', 'Nacken, Halswirbelsäule', 'Ausführung: Im Sitzen den Kopf sanft zur Seite neigen, bis eine Dehnung im seitlichen Nacken spürbar ist, Position halten, Seite wechseln. Ausrüstung: keine, ggf. Stuhl. Worauf achten: Bewegung sehr sanft und ohne Ziehen mit der Hand am Kopf, gleichmäßige Atmung.', 'Mobilisation', 'sonstige', null),
('Brustdehnung im Türrahmen', 'Brust, Schultern', 'Ausführung: Unterarm im rechten Winkel an den Türrahmen anlegen und den Oberkörper leicht nach vorn drehen, bis eine Dehnung in der Brust spürbar ist, Seite wechseln. Ausrüstung: Türrahmen. Worauf achten: Dehnung sanft aufbauen, keine ruckartigen Bewegungen, gleichmäßige Atmung.', 'Mobilisation', 'push_oberkoerper', null),
('Latissimus-Dehnung an der Stange', 'Rücken, Latissimus', 'Ausführung: An einer Stange oder einem festen Halt mit gestreckten Armen hängen bzw. das Becken nach hinten absenken, bis eine Dehnung im seitlichen Rücken spürbar ist. Ausrüstung: Klimmzugstange oder fester Halt. Worauf achten: Schultern entspannt, Dehnung langsam aufbauen, gleichmäßige Atmung.', 'Mobilisation', 'pull_oberkoerper', null),
('Hüftbeuger-Dehnung im Ausfallschritt', 'Hüftbeuger', 'Ausführung: Im tiefen Ausfallschritt das Becken nach vorn-unten schieben, bis eine Dehnung in der Hüftvorderseite des hinteren Beins spürbar ist, Position halten, Seite wechseln. Ausrüstung: Matte. Worauf achten: Oberkörper aufrecht, Becken nicht zur Seite kippen, sanft in die Dehnung gehen.', 'Mobilisation', 'vordere_beinkette', null),
('Wadendehnung an der Wand', 'Waden', 'Ausführung: Mit gestrecktem hinteren Bein und aufgesetzter Ferse gegen eine Wand lehnen, bis eine Dehnung in der Wade spürbar ist, Position halten, Seite wechseln. Ausrüstung: Wand. Worauf achten: Ferse bleibt am Boden, Fuß zeigt gerade nach vorn, Dehnung langsam aufbauen.', 'Mobilisation', 'hintere_beinkette', null),
('Piriformis-Dehnung (Figure-4)', 'Gesäß, Hüfte', 'Ausführung: In Rückenlage einen Knöchel auf das gegenüberliegende Knie legen und das freie Bein zur Brust heranziehen, bis eine Dehnung im Gesäß spürbar ist, Seite wechseln. Ausrüstung: Matte. Worauf achten: Unterer Rücken bleibt am Boden, Dehnung sanft aufbauen, gleichmäßige Atmung.', 'Mobilisation', 'hintere_beinkette', null),
('Schmetterlingsdehnung', 'Adduktoren, Innenschenkel', 'Ausführung: Im Sitzen die Fußsohlen zusammenführen und die Knie sanft mit den Ellbogen Richtung Boden drücken. Ausrüstung: Matte. Worauf achten: Rücken gerade halten, Dehnung langsam und ohne Wippen aufbauen.', 'Mobilisation', 'sonstige', null),
('Rumpfrotation im Stehen', 'Rumpf, Wirbelsäule', 'Ausführung: Im hüftbreiten Stand den Oberkörper locker von einer Seite zur anderen rotieren lassen, Arme schwingen dabei entspannt mit. Ausrüstung: keine. Worauf achten: Hüfte bleibt stabil nach vorn ausgerichtet, Bewegung kommt aus der Brustwirbelsäule.', 'Mobilisation', 'sonstige', null),
('Kindhaltung (Child''s Pose)', 'Rücken, Hüfte', 'Ausführung: Aus dem Fersensitz die Arme nach vorn ausstrecken und den Oberkörper Richtung Boden absenken, Position halten. Ausrüstung: Matte. Worauf achten: Gesäß bleibt auf oder nah an den Fersen, Atmung tief und ruhig in den Rücken.', 'Mobilisation', 'rumpf_hinten', null),
('Thread the Needle (dynamische BWS-Rotation)', 'Brustwirbelsäule, Schultern', 'Ausführung: Im Vierfüßlerstand einen Arm unter dem Körper hindurchführen, bis die Schulter den Boden berührt, dann zurückrotieren und den gleichen Arm zur Decke strecken. Ausrüstung: Matte. Worauf achten: Hüfte bleibt ruhig, Bewegung kommt aus der Brustwirbelsäule, langsames Tempo.', 'Mobilisation', 'sonstige', null),
('Hüftöffner im Kniestand', 'Hüfte', 'Ausführung: Im hohen Kniestand mit einem aufgestellten Bein das Becken kontrolliert kreisen lassen bzw. seitlich verlagern, um die Hüfte zu öffnen. Ausrüstung: Matte. Worauf achten: Oberkörper aufrecht, Bewegung ruhig und im schmerzfreien Bereich.', 'Mobilisation', 'vordere_beinkette', null),
('Schultermobilisation mit dem Stab', 'Schultern', 'Ausführung: Einen Stab oder Handtuch mit beiden Händen breit greifen und über den Kopf nach hinten führen, so weit es die Beweglichkeit zulässt, dann zurück nach vorn. Ausrüstung: Stab, Besenstiel oder Handtuch. Worauf achten: Griffbreite so wählen, dass die Bewegung schmerzfrei bleibt, langsames Tempo.', 'Mobilisation', 'sonstige', null),
('Handgelenk-Mobilisation', 'Handgelenke, Unterarme', 'Ausführung: Die Handgelenke abwechselnd kreisen lassen sowie die Hände bei gestreckten Armen nach oben und unten abknicken. Ausrüstung: keine. Worauf achten: Bewegung langsam und im schmerzfreien Bereich, keine ruckartigen Bewegungen.', 'Mobilisation', 'sonstige', null),
('Knöchelmobilisation', 'Sprunggelenke', 'Ausführung: Im Sitzen oder Stehen die Füße abwechselnd kreisen lassen sowie die Zehenspitzen abwechselnd Richtung Schienbein ziehen und wieder strecken. Ausrüstung: keine. Worauf achten: Bewegung kontrolliert durch den vollen Bewegungsradius führen.', 'Mobilisation', 'sonstige', null),
('Thorakale Rotation im Vierfüßlerstand', 'Brustwirbelsäule', 'Ausführung: Im Vierfüßlerstand eine Hand hinter den Kopf legen und den Ellbogen Richtung Decke rotieren, Blick folgt dem Ellbogen, dann zurück und Seite wechseln. Ausrüstung: Matte. Worauf achten: Hüfte bleibt ruhig, Bewegung kommt ausschließlich aus der Brustwirbelsäule.', 'Mobilisation', 'sonstige', null),
('Beinschwünge seitlich', 'Hüfte, Beine, Adduktoren', 'Ausführung: Mit Festhalten an einer Wand oder Stange ein Bein locker seitlich vor dem Körper hin- und herschwingen lassen, Seite wechseln. Ausrüstung: Wand oder Stange zum Festhalten. Worauf achten: Oberkörper stabil, Bewegung aus der Hüfte, Amplitude langsam steigern.', 'Mobilisation', 'sonstige', null),
('Frosch-Dehnung', 'Adduktoren, Hüfte', 'Ausführung: Im Vierfüßlerstand die Knie breit auseinander positionieren und das Becken langsam nach hinten Richtung Fersen schieben, bis eine Dehnung in der Leiste spürbar ist. Ausrüstung: Matte. Worauf achten: Dehnung langsam aufbauen, im schmerzfreien Bereich bleiben, gleichmäßige Atmung.', 'Mobilisation', 'sonstige', null),
('Kobra-Dehnung', 'Bauch, unterer Rücken', 'Ausführung: In Bauchlage die Hände unter den Schultern aufsetzen und den Oberkörper langsam nach oben drücken, Becken bleibt am Boden. Ausrüstung: Matte. Worauf achten: Bewegung langsam aufbauen, kein Schmerz im unteren Rücken, Schultern entspannt.', 'Mobilisation', 'rumpf_hinten', null),
('Vorbeuge im Stehen', 'Hintere Oberschenkelmuskulatur, Rücken', 'Ausführung: Im Stand mit leicht gebeugten Knien den Oberkörper locker nach vorn hängen lassen, Arme und Kopf hängen entspannt. Ausrüstung: keine. Worauf achten: Dehnung passiv wirken lassen, Knie leicht beugen bei Bedarf, langsam wieder aufrichten.', 'Mobilisation', 'hintere_beinkette', null),
('Große Armkreise', 'Schultern', 'Ausführung: Im Stand beide Arme mit maximaler Reichweite große Kreise nach vorn und anschließend nach hinten ziehen lassen. Ausrüstung: keine. Worauf achten: Bewegung groß und kontrolliert, Rumpf bleibt stabil.', 'Mobilisation', 'sonstige', null),
('Faszienrolle Rücken', 'Rücken', 'Ausführung: Mit der Faszienrolle unter dem oberen Rücken liegend langsam vor- und zurückrollen, an Verspannungspunkten kurz verweilen. Ausrüstung: Faszienrolle. Worauf achten: Nacken entspannt, Bauch angespannt, Bewegung langsam, unteren Rücken aussparen.', 'Mobilisation', 'sonstige', null),
('Faszienrolle Oberschenkel', 'Oberschenkel, IT-Band', 'Ausführung: Mit der Faszienrolle unter dem Oberschenkel liegend/gestützt langsam vor- und zurückrollen, an Verspannungspunkten kurz verweilen. Ausrüstung: Faszienrolle. Worauf achten: Bewegung langsam, Rumpf stabil, Druck über die Armstützung dosieren.', 'Mobilisation', 'sonstige', null),
('Assault Bike (Air Bike)', 'Ganzkörper & Herz-Kreislauf-System', 'Ausführung: Auf dem Air Bike gleichzeitig in die Pedale treten und die Arme aktiv mitbewegen, Intensität über Tempo steuern. Ausrüstung: Assault Bike/Air Bike. Worauf achten: Aufrechte Haltung, gleichmäßiger Rhythmus zwischen Armen und Beinen, Intensität über Herzfrequenz oder Tempo steuern.', 'Cardio', 'sonstige', null),
('Seilspringen (Jump Rope)', 'Waden, Ganzkörper & Herz-Kreislauf-System', 'Ausführung: Mit dem Springseil in gleichmäßigem Rhythmus über die Fußballen springen, Handgelenke drehen das Seil. Ausrüstung: Springseil. Worauf achten: Weiche, geräuscharme Landung über die Fußballen, Ellbogen nah am Körper, aufrechte Haltung.', 'Cardio', 'sonstige', null),
('Schlittenschieben (Sled Push)', 'Beine, Gesäß & Herz-Kreislauf-System', 'Ausführung: Den beladenen Schlitten mit gestreckten Armen vor dem Körper über eine festgelegte Strecke schieben. Ausrüstung: Sled/Schlitten mit Gewicht. Worauf achten: Rücken gerade, Antrieb aus den Beinen, kurze kraftvolle Schritte.', 'Cardio', 'sonstige', null),
('Schlittenziehen (Sled Pull)', 'Rücken, Beine & Herz-Kreislauf-System', 'Ausführung: Den beladenen Schlitten über ein Seil oder einen Gurt rückwärts oder vorwärts ziehend über eine festgelegte Strecke bewegen. Ausrüstung: Sled/Schlitten mit Gewicht, Seil oder Zuggurt. Worauf achten: Rücken gerade, gleichmäßiges Tempo, Rumpf stabil.', 'Cardio', 'sonstige', null),
('Tabata-Intervalle (20/10, freie Übungsauswahl)', 'Ganzkörper & Herz-Kreislauf-System', 'Ausführung: 20 Sekunden maximale Intensität bei einer frei wählbaren Übung (z. B. Burpees, Mountain Climbers), gefolgt von 10 Sekunden Pause, über mehrere Runden wiederholen. Ausrüstung: je nach gewählter Übung. Worauf achten: Technik auch bei hoher Intensität sauber halten, Belastung an die Fitness anpassen.', 'Cardio', 'sonstige', null),
('Boxen am Sandsack', 'Ganzkörper, Arme, Schultern', 'Ausführung: Im lockeren Stand Schlagkombinationen (Jab, Cross, Haken) mit Armen und Rumpfrotation gegen den Sandsack ausführen. Ausrüstung: Sandsack, ggf. Boxhandschuhe/Bandagen. Worauf achten: Handgelenke stabil halten, Rotation aus der Hüfte, lockere Beinarbeit.', 'Cardio', 'sonstige', null),
('Skaters (seitliche Sprünge)', 'Beine, Gesäß, Gleichgewicht', 'Ausführung: Seitliche Sprünge von einem Bein auf das andere, das hintere Bein schwingt dabei hinter dem Standbein her, im Rhythmus die Seite wechseln. Ausrüstung: keine. Worauf achten: Weiche Landung, Knie leicht gebeugt, Rumpf stabil.', 'Cardio', 'sonstige', null),
('Squat Jumps (Kniebeugensprünge)', 'Beine, Gesäß', 'Ausführung: Aus der Kniebeuge-Position explosiv nach oben abspringen, weich über die Fußballen landen und direkt in die nächste Kniebeuge übergehen. Ausrüstung: keine. Worauf achten: Weiche Landung mit gebeugten Knien, Rumpf stabil, Rhythmus an die eigene Fitness anpassen.', 'Cardio', 'sonstige', null),
('Tuck Jumps (Strecksprünge mit Knieanzug)', 'Beine, Gesäß', 'Ausführung: Aus dem Stand explosiv nach oben springen und dabei beide Knie zur Brust anziehen, weich landen. Ausrüstung: keine. Worauf achten: Weiche Landung, Rumpf stabil, ausreichend Platz nach oben und zur Seite einplanen.', 'Cardio', 'sonstige', null),
('Schattenboxen (Shadow Boxing)', 'Ganzkörper, Arme', 'Ausführung: Freie Schlagkombinationen mit aktiver Beinarbeit ohne Gerät oder Partner ausführen, kontinuierlich in Bewegung bleiben. Ausrüstung: keine. Worauf achten: Lockere, kontrollierte Bewegungen, gleichmäßiger Rhythmus, aufrechte Grundhaltung.', 'Cardio', 'sonstige', null),
('Treppenlaufen (reale Treppe)', 'Beine, Gesäß & Herz-Kreislauf-System', 'Ausführung: Zügiges Treppauf- und -absteigen über mehrere Stockwerke oder eine Treppenstrecke, Tempo an die Fitness anpassen. Ausrüstung: Treppe. Worauf achten: Fuß vollständig aufsetzen, Geländer nur zur Sicherheit nutzen, beim Abstieg besonders auf sicheren Tritt achten.', 'Cardio', 'sonstige', null),
('Walking-Intervalle im Freien', 'Beine & Herz-Kreislauf-System', 'Ausführung: Zügiges Gehen im Freien mit wechselnden Tempo-Intervallen (z. B. 2 Minuten schnell, 1 Minute locker), aktiver Armeinsatz. Ausrüstung: keine, festes Schuhwerk. Worauf achten: Aufrechte Haltung, gleichmäßiger Atemrhythmus, Untergrund und Wetter berücksichtigen.', 'Cardio', 'sonstige', null),
('Schwimmen (Bahnenziehen)', 'Ganzkörper & Herz-Kreislauf-System (gelenkschonend)', 'Ausführung: Kontinuierliches Bahnenziehen in einem Schwimmstil der Wahl (z. B. Kraul, Brust), Tempo und Distanz an die Fitness anpassen. Ausrüstung: Schwimmbad. Worauf achten: Gleichmäßige Atmung, saubere Technik vor Tempo, ausreichend Aufwärmen.', 'Cardio', 'sonstige', null),
('Tanz-Cardio (freies Rhythmustraining)', 'Ganzkörper, Koordination & Herz-Kreislauf-System', 'Ausführung: Freies, rhythmisches Bewegen zu Musik mit kontinuierlichem Einsatz von Armen und Beinen, Intensität über Tempo und Bewegungsumfang steuern. Ausrüstung: keine, ggf. Musik. Worauf achten: Gelenkschonende, fließende Bewegungen, ausreichend Platz einplanen.', 'Cardio', 'sonstige', null),
('Indoor Cycling / Spinning (hohe Intensität)', 'Beine & Herz-Kreislauf-System', 'Ausführung: Auf dem Spinning-Rad im Sitzen oder Wiegetritt mit wechselnder Intensität und Widerstand fahren. Ausrüstung: Spinning-/Indoor-Cycling-Rad. Worauf achten: Sattel- und Lenkerhöhe korrekt einstellen, gleichmäßige Trittfrequenz, Widerstand schrittweise steigern.', 'Cardio', 'sonstige', null),
('Medizinball-Slams', 'Ganzkörper, Rumpf, Schultern', 'Ausführung: Den Medizinball mit gestreckten Armen über den Kopf heben und mit voller Kraft auf den Boden schleudern, auffangen und wiederholen. Ausrüstung: Medizinball (wallfest). Worauf achten: Rumpf angespannt, Bewegung aus der Hüfte und den Schultern, Knie beim Aufheben leicht beugen.', 'Cardio', 'sonstige', null),
('Rudergerät (Dauerbelastung)', 'Ganzkörper & Herz-Kreislauf-System', 'Ausführung: Am Rudergerät im gleichmäßigen Tempo über eine längere Distanz oder Zeit rudern, Beine-Rücken-Arme-Sequenz konstant halten. Ausrüstung: Rudergerät. Worauf achten: Bewegungsreihenfolge Beine-Rücken-Arme einhalten, aufrechter Oberkörper, gleichmäßiges Tempo statt Sprints.', 'Cardio', 'sonstige', null),
('High Knees (schnelles Kniehebellauf auf der Stelle)', 'Beine, Hüftbeuger & Herz-Kreislauf-System', 'Ausführung: Auf der Stelle mit hoher Frequenz die Knie abwechselnd bis über Hüfthöhe anheben, aktiver Armeinsatz. Ausrüstung: keine. Worauf achten: Aufrechte Haltung, Landung über den Fußballen, hohe Frequenz statt große Schritte.', 'Cardio', 'sonstige', null),
('Plank Jacks (Unterarmstütz mit Beinsprung)', 'Rumpf, Beine & Herz-Kreislauf-System', 'Ausführung: Im Unterarmstütz die Beine mit einem kleinen Sprung auseinander und wieder zusammenführen, Rumpf bleibt dabei stabil. Ausrüstung: Matte. Worauf achten: Becken bleibt ruhig und auf einer Höhe, kontrollierte Landung, Tempo an die Fitness anpassen.', 'Cardio', 'sonstige', null),
('Laufband-Sprintintervalle (Tempowechsel)', 'Beine & Herz-Kreislauf-System', 'Ausführung: Auf dem Laufband im Wechsel kurze Sprintphasen mit hoher Geschwindigkeit und längere Erholungsphasen im Gehen oder lockeren Laufen kombinieren. Ausrüstung: Laufband. Worauf achten: Geschwindigkeit schrittweise steigern, sichere Handhabung der Konsole während des Tempowechsels, ausreichend Aufwärmen vor dem ersten Sprint.', 'Cardio', 'sonstige', null);
